namespace sv_3d4bc3d338e64190afad7846a80b8195.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Components subscribe to <see cref="OnChange"/> to react when the selection changes.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    public string CurrentWarehouseId { get; private set; } = AvailableWarehouses[0].Id;
    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == CurrentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (warehouseId == CurrentWarehouseId)
            return;

        CurrentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_3d4bc3d338e64190afad7846a80b8195.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per circuit.
/// <see cref="GetLowStockCountAsync"/> simulates a database query.
/// <see cref="OnAlertCountChanged"/> notifies ALL subscribed components when
/// new data arrives, regardless of which component triggered the refresh.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query — returns a random number 0–15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches the latest count for the given warehouse, stores it, and
    /// fires <see cref="OnAlertCountChanged"/> so every subscriber re-renders.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

