@rendermode InteractiveServer
@inject WarehouseState Warehouse
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label text-white mb-1" for="warehouseSelect">Current Warehouse</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@Warehouse.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _handler;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            Warehouse.SetWarehouse(newId);
        }
    }

    public void Dispose() => Warehouse.OnChange -= _handler;
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose() => AlertService.OnAlertCountChanged -= _handler;
}

@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @Warehouse.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">Viewing: <strong>@Warehouse.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentAlertCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentAlertCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.CurrentAlertCount
                </p>
                <p class="text-muted">
                    items below minimum level
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p>
                    Polling is <strong class="text-success">active</strong> —
                    checking every 10 seconds.
                </p>
                <p class="text-muted mb-0">
                    Last checked: @_lastChecked?.ToString("T")
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;
    private DateTime? _lastChecked;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to warehouse changes so we refresh immediately on switch
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAlertCountAsync(Warehouse.CurrentWarehouseId);
            _lastChecked = DateTime.Now;
            StateHasChanged();
        });
        Warehouse.OnChange += _warehouseHandler;

        // Subscribe to alert changes fired by RefreshAlertCountAsync
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(Warehouse.CurrentWarehouseId);
        _lastChecked = DateTime.Now;

        // Start polling
        _cts = new CancellationTokenSource();
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        try
        {
            while (await _timer.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAlertCountAsync(Warehouse.CurrentWarehouseId);
                    _lastChecked = DateTime.Now;
                    StateHasChanged();
                });
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    public void Dispose()
    {
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

